''' This is a file containing some common operations on the objects'''

import squishtest
from interops.libraries.squish_actions import common
from interops.libraries.miscellaneous.decorators import log_decorator

def clear_text(object):
    '''
    Use this to clear text from an object
    '''
    obj = None
    try:
        obj = common.find_object(object, 200)
    except Exception:
        return obj # not ready/enabled
    if  obj and hasattr(obj, "text") and len(getattr(obj, "text")) > 0:
        squishtest.mouseClick(obj)
        squishtest.snooze(0.1)
        squishtest.nativeType("<Home>")
        squishtest.snooze(0.5)
        squishtest.nativeType("<Shift+End>")
        squishtest.snooze(0.1)
        squishtest.nativeType("<Delete>")
        squishtest.snooze(0.1)
    return obj

def set_text(object, text):
    '''
    Use this function to set an object's text
    '''
    obj = clear_text(object)
    if obj:
        squishtest.mouseClick(obj)
        squishtest.type(obj, text)
        return True
    return False

def get_text(object):
    '''
    Use this function to get an object's text
    '''
    text = ""
    try:
        obj = squishtest.waitForObject(object, 200)
        if obj:
            text = getattr(obj, "text", "")
    except LookupError:
        if 'container' in object:
            o = find_object_itself(object)
            if o:
                text = getattr(o, "text", "")
    return str(text)

def find_any_object(objects, timeout = 200):
    '''
    Find any object of a list/array
    '''
    for  obj in objects:
        try:
            o = common.find_object(obj, 200)
            return o
        except Exception:
            continue
    return None

def find_object_itself(obj, uniqattr = 'id'):
    '''
    Find an object via its container by a unique attribute like 'id', this is especially useful for an object that is not enabled.
    '''
    container = obj.get('container')
    attr =  obj.get(uniqattr)
    if container and attr:
        try:
            parent = squishtest.waitForObject(container)
            children = squishtest.object.children(parent)
            for child in children:
                if child.type == obj.get('type'):
                    if getattr(child, uniqattr, "") == attr or str(getattr(child, uniqattr, "")) == str(attr):
                        return child
        except Exception:
            return None
    return None

def get_children(obj):
    '''
    Get the chilren of an object.
    '''
    if obj:
        o = squishtest.findObject(obj)
        if o:
            return squishtest.object.children(o)
    return []

def get_list_items(obj):
    '''
    Get the list items from a List or a ComboBox
    '''
    itemList = []
    children = get_children(obj)
    for child in children:
        if (child.type == "ListItem" or child.type == "ComboBoxItem") and hasattr(child, "text"):
            itemList.append(child.text)
    return itemList

@log_decorator
def click_item(obj, item:str, skipping_click_itself = False):
    '''
    Click an item in a list, skipping_click_itsel flag indicates whether the list needs to be clicked first.
    return True if clicked, otherwise False. It does not throw for an exception.
    '''
    clicked = False
    try:
        if not skipping_click_itself:
            squishtest.mouseClick(obj)
        squishtest.mouseClick(squishtest.waitForObjectItem(obj, item))
        clicked = True
    except Exception as ex:
        print(ex)
    return clicked
